/* Buildless documentation application. All business records below are fictional. */
(function(){
'use strict';
const DS=window.SeazenDS,R=window.SeazenRules,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name='search')=>{const paths={search:'<circle cx="5" cy="5" r="3.5"/><path d="m8 8 3 3"/>',value:'<rect x="1" y="4" width="7" height="7"/><path d="M4 1h7v7"/>',calendar:'<rect x="1" y="2" width="10" height="9"/><path d="M1 5h10M4 0v4M8 0v4"/>',empty:'<path d="M2 3h8v7H2zM4 1h4v3H4zM4 7h4"/>',edit:'<path d="m2 8 6-6 2 2-6 6-3 1zM7 3l2 2"/>',close:'<path d="m3 3 6 6M9 3 3 9"/>'};return `<svg class="sz-icon" aria-hidden="true" viewBox="0 0 12 12">${paths[name]||paths.search}</svg>`;};
const baseRecords=()=>[
 {id:'DEMO-001',name:'示例项目 A · 铺位意向合同',status:'unsubmitted',brand:'示例品牌 A',area:128.5,amount:1268000,date:'2026/11/03'},
 {id:'DEMO-002',name:'示例项目 B · 商务洽谈合同',status:'approving',brand:'示例品牌 B',area:260,amount:2385600,date:'2026/11/02'},
 {id:'DEMO-003',name:'示例项目 C · 招商合作合同',status:'approved',brand:'示例品牌 C',area:96,amount:855000,date:'2026/10/31'},
 {id:'DEMO-004',name:'示例项目 A · 配套服务合同',status:'returned',brand:'示例品牌 D',area:0,amount:0,date:'2026/10/29'},
 {id:'DEMO-005',name:'示例项目 B · 业态调整合同',status:'voided',brand:'示例品牌 E',area:180.5,amount:null,date:'2026/10/28'},
 {id:'DEMO-006',name:'示例项目 C · 品牌入驻合同',status:'rejected',brand:'示例品牌 F',area:325,amount:3518000,date:'2026/10/27'}
];
let fieldCounter=0;
let records=baseRecords(),selected=new Set(['DEMO-001']),org='project',role='editor',busy=false,query='',filterStatus='',sortDesc=false,templateMode='list',currentPage='',modalReturn=null,calendarTarget='',calendarYear=2026,calendarMonth=10,treeOpen=true,tokens=['示例项目 A','示例项目 B'];
const actionNames={create:'新增',edit:'修改',delete:'删除',view:'查看',submit:'提交审批',viewApproval:'查看审批',export:'导出'};
const allActions=Object.keys(actionNames);
function context(){return {permissions:role==='viewer'?['view','viewApproval']:role==='noexport'?allActions.filter(x=>x!=='export'):allActions,organization:org,selection:records.filter(r=>selected.has(r.id)),busy,submitStatuses:null};}
function rulesTable(rows){return `<div class="responsive-table"><table class="prop-table"><thead><tr><th>项目</th><th>规格 / 规则</th><th>使用说明</th></tr></thead><tbody>${rows.map(x=>`<tr>${x.map(y=>`<td>${esc(y)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function listRules(rows){return `<ul class="rule-list">${rows.map(x=>`<li><span class="rule-id">${esc(x[0])}</span><span class="badge ${x[1]==='待确认'||x[1]==='建议'?'proposed':x[1]==='可'?'flex':'hard'}">${esc(x[1])}</span><span>${esc(x[2])}</span></li>`).join('')}</ul>`;}
function section(id,title,content){return `<section class="doc-section" id="${id}"><h2>${title}</h2>${content}</section>`;}
function codeBlock(text){return `<div class="code-block"><button class="copy-code" data-copy-code>复制</button><pre>${esc(text)}</pre></div>`;}
function specBox(title,html,{flush=false,note='组件画布按 1:1 的 12px 最小字号适配规范显示 · 示例数据均为虚构',code=''}={}){return `<div class="spec-box"><div class="spec-toolbar"><span class="dots"><i></i><i></i><i></i></span>${esc(title)}<span class="right"><span class="badge">HTML / CSS</span><span>100%</span></span></div><div class="spec-content ${flush?'flush':''}"><div class="sz-scope">${html}</div></div><div class="spec-note">${esc(note)}</div>${code?`<details><summary>查看示例代码</summary>${codeBlock(code)}</details>`:''}</div>`;}
function sourceLine(page){return `<div class="source-line"><span class="badge ${['states','upload'].includes(page.id)?'proposed':''}">${['states','upload'].includes(page.id)?'基线 + 补充建议':'基线整合'}</span><span>依据 ${esc(page.source)}</span><a href="#sources">查看依据 ↗</a></div>`;}
function field(label,input,{required=false,full=false}={}){let match=input.match(/\bid="([^"]+)"/);const id=match?match[1]:`field-${++fieldCounter}`;if(!match)input=input.replace(/<(input|select|textarea)\b/,`<$1 id="${id}"`);return `<div class="sz-field${full?' full':''}"><label for="${id}">${required?'<span class="sz-required">*</span>':''}${esc(label)}:</label>${input}</div>`;}
function input(label,value='',attrs=''){const extra=attrs.match(/class="([^"]*)"/);const cls=extra?extra[1]:"sz-input";attrs=attrs.replace(/class="[^"]*"/,"");return `<input class="${cls}" aria-label="${esc(label)}" value="${esc(value)}" ${attrs}>`;}
function selectInput(label,options,attrs=''){return `<select class="sz-select" aria-label="${esc(label)}" ${attrs}>${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}">${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select>`;}
function linkedInput(label,id,value='',type='value'){return `<span class="sz-with-icon">${input(label,value,`id="${id}"`)}<button data-action="${type==='calendar'?'calendar':'valuehelp'}" data-target="${id}" aria-label="选择${esc(label)}" title="选择${esc(label)}">${icon(type)}</button></span>`;}
function status(s){return `<span class="sz-status ${s==='approved'?'approved':''}">${esc(R.labels[s]||s)}</span>`;}
function toolbar(title='合同',count=6){const c=context();return `<div class="sz-toolbar"><h3>${esc(title)} (${count})</h3><div class="sz-toolbar-actions">${allActions.map(a=>{const r=R.evaluate(a,c);return `<span title="${esc(r.reason||actionNames[a])}"><button class="sz-btn transparent" data-action="business" data-business="${a}" ${r.visible?'':'hidden'} ${r.enabled?'':'disabled'} aria-label="${esc(actionNames[a]+(r.reason?'：'+r.reason:''))}">${actionNames[a]}</button></span>`;}).join('')}</div></div>`;}
function visibleRecords(){return records.filter(r=>!r.deleted&&(!query||`${r.id}${r.name}${r.brand}`.toLowerCase().includes(query.toLowerCase()))&&(!filterStatus||r.status===filterStatus)).sort((a,b)=>sortDesc?b.amount-a.amount:0);}
function tableMarkup({selectable=true,simple=false}={}){const rows=visibleRecords();return `<div class="sz-table-scroll"><table class="sz-table ${simple?'responsive':''}" aria-label="虚构合同示例列表"><colgroup>${selectable?'<col style="width:24px">':''}<col style="width:40px"><col style="width:85px"><col style="width:100px"><col style="width:210px"><col style="width:85px"><col style="width:90px"><col style="width:105px"><col style="width:100px"></colgroup><thead><tr>${selectable?`<th><input class="sz-check" type="checkbox" aria-label="全选当前结果" data-select-all ${rows.length&&rows.every(r=>selected.has(r.id))?'checked':''}></th>`:''}<th>序号</th><th>状态</th><th>单据编号</th><th>合同名称</th><th>品牌</th><th>面积(平方米)</th><th><button class="sz-btn transparent" data-action="sort" aria-label="按金额排序">金额(元) ${sortDesc?'↓':'↕'}</button></th><th>签订日期</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr class="${selected.has(r.id)?'selected':''}" ${selectable?`data-row="${r.id}"`:''}>${selectable?`<td class="center"><input class="sz-check" type="checkbox" aria-label="选择 ${r.id}" data-select-row="${r.id}" ${selected.has(r.id)?'checked':''}></td>`:''}<td class="center">${i+1}</td><td class="center">${status(r.status)}</td><td class="center">${r.id}</td><td class="long" title="${esc(r.name)}">${esc(r.name)}</td><td class="long">${esc(r.brand)}</td><td class="number">${R.formatNumber(r.area)}</td><td class="number">${R.formatNumber(r.amount)}</td><td class="center">${r.date}</td></tr>`).join(''):`<tr><td colspan="${selectable?9:8}" style="height:120px;text-align:center;color:#777">未找到数据。尝试调整过滤器设置。</td></tr>`}</tbody></table></div>`;}
function filterMarkup(){return `<div class="sz-filter" id="demo-filter"><div class="sz-filter-title"><button data-action="toggle-filter" aria-expanded="true">检索条件 ⌄</button></div><div class="sz-filter-fields">${field('合同名称',input('查询合同名称',query,'id="filter-query" placeholder="输入名称、编号或品牌"'))}${field('审批状态',selectInput('查询审批状态',[['','全部状态'],...Object.entries(R.labels)],'id="filter-status"'))}${field('项目',linkedInput('项目','filter-project','示例项目 A'))}${field('开始日期',linkedInput('开始日期','filter-date','','calendar'))}${field('业务类型',selectInput('业务类型',['全部类型','意向合同','商务合同']))}</div><div class="sz-filter-actions"><button class="sz-btn transparent" data-action="reset-filter">重置</button><button class="sz-btn primary" data-action="query">查询</button></div></div>`;}
function workbench({filters=false,controls=false}={}){return `${controls?`<div class="play-controls"><label>组织层级<select id="policy-org" aria-label="组织层级"><option value="project">项目层级</option><option value="region">区域层级</option><option value="group">集团层级</option></select></label><label>首条演示单据状态<select id="policy-status" aria-label="首条演示单据状态">${Object.entries(R.labels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><label>用户权限<select id="policy-role" aria-label="用户权限"><option value="editor">业务操作权限</option><option value="noexport">无导出权限</option><option value="viewer">仅查看权限</option></select></label><label class="inline"><input type="checkbox" id="policy-busy">操作处理中</label><button class="doc-btn small" data-action="reset-demo">重置示例</button></div>`:''}<div class="sz-scope">${filters?filterMarkup()+'<div class="sz-page-gap"></div>':''}<div id="workbench-table">${toolbar('合同',visibleRecords().length)}${tableMarkup()}</div></div><div class="policy-result" id="policy-result">${selectionHint()}</div>`;}
function selectionHint(){const c=context();const selection=c.selection.filter(x=>!x.deleted);return `已选 ${selection.length} 条 · ${org==='project'?'项目':org==='region'?'区域':'集团'}层级${selection.length===1?' · '+R.labels[selection[0].status]:''}。${R.evaluate('submit',c).reason||'未授权操作按权限隐藏。'}`;}
function redrawWorkbench(){const el=$('#workbench-table');if(el)el.innerHTML=toolbar('合同',visibleRecords().length)+tableMarkup();const result=$('#policy-result');if(result)result.textContent=selectionHint();const st=$('#filter-status');if(st)st.value=filterStatus;}
function formMarkup(mode='edit'){const read=mode==='view',ro=read?'readonly':'';return `<div class="sz-page-header"><h3>${read?'查看合同 DEMO-001':'新增合同'}</h3>${read?'':`<button class="sz-btn primary" data-action="save-form">保存</button><span title="提交审批状态规则待产品确认"><button class="sz-btn ghost" disabled>提交审批</button></span>`}<button class="sz-btn ghost" data-action="form-back">返回</button></div><div class="sz-page-gap"></div><form id="demo-business-form" novalidate><section class="sz-section"><h3 class="sz-section-title"><span>基本信息</span></h3><div class="sz-form">${field('合同名称',input('合同名称',read?'示例项目 A · 意向合同':'',`id="form-name" ${ro} required aria-describedby="form-name-error"`),{required:true})}${field('归属项目',input('归属项目','示例项目 A','readonly'))}${field('单据状态',input('单据状态',read?'已审批':'未提交','readonly'))}${field('建筑面积',input('建筑面积',read?'128.50':'',`id="form-area" class="sz-input number" inputmode="decimal" ${ro} aria-describedby="form-area-error" placeholder="平方米"`))}${field('合同金额',input('合同金额',read?'1,268,000.00':'',`id="form-amount" class="sz-input number" inputmode="decimal" ${ro} placeholder="元"`))}${field('签订日期',read?input('签订日期','2026/11/03','readonly'):linkedInput('签订日期','form-date','','calendar'))}${field('业务类型',selectInput('业务类型',['意向合同','商务合同'],read?'disabled':''))}${field('是否含税',`<span><label class="sz-choice"><input class="sz-radio" type="radio" name="tax" value="yes" checked ${read?'disabled':''}>是</label><label class="sz-choice"><input class="sz-radio" type="radio" name="tax" value="no" ${read?'disabled':''}>否</label></span>`)}${field('合同编号',input('合同编号',read?'DEMO-001':'保存后生成','readonly'))}${field('备注',`<textarea class="sz-textarea" aria-label="备注" rows="3" ${ro}>${read?'本页为虚构数据示例。':''}</textarea>`,{full:true})}</div><div id="form-errors" role="alert" style="padding:0 24px;color:var(--sz-error);max-height:200px;overflow:auto"></div></section></form>`;}
const exampleCode={button:'<button class="sz-btn primary">保存</button>\n<button class="sz-btn transparent">修改</button>\n<button class="sz-btn ghost" disabled>提交审批</button>',input:'<label for="contract-name">合同名称</label>\n<input id="contract-name" class="sz-input" required>\n<input class="sz-input number" inputmode="decimal">\n<input class="sz-input" value="示例项目 A" readonly>',table:'<!-- 生产映射：sap.ui.table.Table / SmartTable -->\n<table class="sz-table">\n  <thead><tr><th>金额(元)</th></tr></thead>\n  <tbody><tr><td class="number">1,234,567.00</td></tr></tbody>\n</table>',date:'<!-- HTML 日期外观是示例；生产使用 UI5 DatePicker -->\n<DatePicker displayFormat="yyyy/MM/dd" valueFormat="yyyy-MM-dd" />',form:'<!-- UI5 结构建议，须由前端核验版本 API -->\n<Form editable="true">\n  <layout><ResponsiveGridLayout columnsL="3" columnsM="2" /></layout>\n</Form>',dialog:'<Dialog contentWidth="80%" title="选择项目">\n  <!-- 统一紧凑表单 / 表格 -->\n  <beginButton><Button text="确定" type="Emphasized" /></beginButton>\n  <endButton><Button text="取消" type="Default" /></endButton>\n</Dialog>'};
function demos(kind){
 switch(kind){
 case 'button':return specBox('四种标准外观',`<div class="demo-row"><div><span class="demo-label">强调 · Emphasized</span><button class="sz-btn primary" data-action="info">保存</button></div><div><span class="demo-label">透明 · Transparent</span><button class="sz-btn transparent" data-action="info">修改</button></div><div><span class="demo-label">幽灵 · Ghost</span><button class="sz-btn ghost" data-action="info">返回</button></div><div><span class="demo-label">默认 · Default</span><button class="sz-btn" data-action="info">取消</button></div></div>`,{code:exampleCode.button})+specBox('禁用与加载',`<div class="demo-row"><span title="请选择一条单据"><button class="sz-btn transparent" disabled>删除</button></span><button class="sz-btn primary" disabled>保存</button><button class="sz-btn primary" data-action="loading-button">体验加载</button><button class="sz-btn icon transparent" aria-label="编辑示例单据" title="编辑示例单据" data-action="info">${icon('edit')}</button></div>`,{note:'禁用透明度 50% 为基线；加载反馈与可访问名称为补充建议。'});
 case 'input':return specBox('默认、只读、禁用、校验和主数据选择',`<div class="demo-row"><div class="demo-col">${field('合同名称',input('合同名称','','placeholder="请输入合同名称"'))}${field('项目名称',linkedInput('项目名称','input-project'))}</div><div class="demo-col">${field('只读字段',input('只读字段','示例项目 A','readonly'))}${field('金额',input('金额','1,234,567.00','class="sz-input number" inputmode="decimal"'))}</div><div class="demo-col">${field('禁用字段',input('禁用字段','','disabled placeholder="条件未满足"'))}${field('必填字段',input('必填字段','','class="sz-input sz-error-field" aria-invalid="true" aria-describedby="input-error"')+'<span id="input-error" class="sz-field-error">请填写合同名称</span>',{required:true})}</div></div>`,{code:exampleCode.input});
 case 'select':return specBox('固定选项、可过滤选项与多选',`<div class="demo-row"><div class="demo-col">${field('业务类型',selectInput('业务类型',['请选择','意向合同','商务合同','招商合同']))}</div><div class="demo-col">${field('品牌检索',input('品牌检索','','list="brands" placeholder="输入 A / B 过滤"')+'<datalist id="brands"><option>示例品牌 A</option><option>示例品牌 B</option><option>示例品牌 C</option></datalist>')}</div><div class="demo-col"><label class="demo-label">状态多选 · 点击展开</label><details style="border:1px solid #89919a"><summary style="font-size:12px;padding:0 6px">选择状态</summary><div style="padding:6px">${Object.entries(R.labels).map(([v,t])=>`<label style="display:block"><input type="checkbox" class="sz-check" data-multiselect value="${v}">${t}</label>`).join('')}</div></details><span id="select-summary" class="sz-status">尚未选择</span></div></div>`);
 case 'date':return specBox('单日与起止日期',`<div class="demo-row"><div class="demo-col">${field('签订日期',linkedInput('签订日期','single-date','2026/11/03','calendar'))}</div><div class="demo-col">${field('开始日期',linkedInput('开始日期','range-start','','calendar'))}</div><div class="demo-col">${field('结束日期',linkedInput('结束日期','range-end','','calendar'))}</div></div><p id="date-feedback" role="status" style="margin:12px 0 0;color:#777">点击日历图标选择，也可直接输入 yyyy/MM/dd。</p>`,{code:exampleCode.date});
 case 'choice':return specBox('互斥单选与独立复选',`<div class="demo-row"><div><span class="demo-label">是否含税</span><label class="sz-choice"><input class="sz-radio" type="radio" name="example-tax" checked>是</label><label class="sz-choice"><input class="sz-radio" type="radio" name="example-tax">否</label></div><div><span class="demo-label">业务类型</span><label class="sz-choice"><input class="sz-check" type="checkbox" checked>意向合同</label><label class="sz-choice"><input class="sz-check" type="checkbox">商务合同</label></div><div><span class="demo-label">不可用</span><label class="sz-choice"><input class="sz-check" type="checkbox" disabled>条件未满足</label></div></div>`);
 case 'multiinput':return specBox('可添加与移除的筛选条件',`<div style="max-width:500px"><label for="token-input">归属项目</label><div class="sz-multi" id="tokens-box">${tokenMarkup()}</div><p style="color:#777;margin:12px 0">输入名称并回车添加；点击 × 移除。</p></div>`);
 case 'upload':return specBox('本地文件选择演示',`<input type="file" id="demo-file" multiple class="visually-hidden" aria-label="选择演示附件"><button class="sz-btn" data-action="upload">选择附件</button><span style="margin-left:6px;color:#777">仅在本地显示，不上传服务器</span><ul id="file-list" style="padding-left:12px"></ul>`,{note:'选型来自 S1；文件列表与移除交互为补充建议，未设置未经确认的大小上限。'});
 case 'table':return specBox('选择、排序、查询与状态操作',workbench({filters:true}),{flush:true,code:exampleCode.table});
 case 'tree':return specBox('可展开的科目层级',treeMarkup());
 case 'toolbar':return specBox('标准业务工具栏',workbench(),{flush:true});
 case 'status':return specBox('状态与业务含义',`<div class="demo-row">${Object.keys(R.labels).map(s=>`<div><span class="demo-label">${s==='approved'?'统一名称 · 品牌蓝':'默认状态 · 中性灰'}</span>${status(s)}</div>`).join('')}</div>`);
 case 'tabs':return specBox('同页面内容分组',`<div class="sz-tabs" role="tablist" aria-label="合同信息分组"><button class="sz-tab" role="tab" id="tab-basic" data-action="tab" data-tab="basic" aria-controls="tab-panel" aria-selected="true">基本信息</button><button class="sz-tab" role="tab" id="tab-detail" data-action="tab" data-tab="detail" aria-controls="tab-panel" aria-selected="false" tabindex="-1">条款明细</button><button class="sz-tab" role="tab" id="tab-attachment" data-action="tab" data-tab="attachment" aria-controls="tab-panel" aria-selected="false" tabindex="-1">附件 (2)</button></div><div id="tab-panel" role="tabpanel" aria-labelledby="tab-basic" style="padding:24px">合同编号：DEMO-001　　归属项目：示例项目 A　　状态：未提交</div>`,{flush:true});
 case 'dialog':return specBox('三种任务边界',`<div class="demo-row"><button class="sz-btn" data-action="valuehelp" data-target="">打开值帮助选择</button><button class="sz-btn" data-action="confirm-demo">打开确认弹窗</button><button class="sz-btn" data-action="error-demo">打开错误弹窗</button></div>`,{code:exampleCode.dialog});
 case 'message':return specBox('页面提示与操作结果',`<div class="sz-message"><span aria-hidden="true">ⓘ</span><span>当前为未提交单据，可编辑后保存。提交审批的可用状态需由产品确认。</span></div><div style="margin-top:24px"><button class="sz-btn" data-action="info">体验信息弹窗</button><button class="sz-btn" data-action="error-demo">体验错误弹窗</button></div>`);
 case 'states':return `<div class="play-controls"><label>页面状态<select id="state-select" aria-label="页面状态"><option value="initial">尚未查询</option><option value="empty">查询无结果</option><option value="loading">加载中</option><option value="error">加载失败</option><option value="denied">无权限</option><option value="success">加载成功</option></select></label></div>${specBox('结果区域状态',`<div id="state-demo">${emptyMarkup('initial')}</div>`,{flush:true,note:'空状态文案来自实页；加载、失败及无权限呈现为建议补充。'})}`;
 case 'form':return specBox('可填写、可校验的三列表单',formMarkup(),{flush:true,code:exampleCode.form});
 case 'layout':return specBox('统一壳层与列表结构',templateShell('list'),{flush:true,note:'壳层导航宽度为展示建议；业务区控件尺寸继承 Compact 基线。'});
 default:return '';
 }
}
function tokenMarkup(){return tokens.map((t,i)=>`<span class="sz-token">${esc(t)}<button data-action="remove-token" data-index="${i}" aria-label="移除${esc(t)}">×</button></span>`).join('')+'<input id="token-input" aria-label="添加归属项目，回车确认" style="border:0;outline:none;min-width:70px;width:90px;font-size:12px" placeholder="输入并回车">';}
function treeMarkup(){return `<table class="sz-table" style="min-width:450px"><thead><tr><th>科目名称</th><th>科目编码</th><th>预算金额(元)</th></tr></thead><tbody><tr><td><button class="sz-btn transparent" data-action="tree" aria-expanded="${treeOpen}">${treeOpen?'⌄':'›'} 运营费用</button></td><td class="center">DEMO-100</td><td class="number">1,268,000.00</td></tr>${treeOpen?'<tr><td style="padding-left:24px">物业服务费</td><td class="center">DEMO-101</td><td class="number">860,000.00</td></tr><tr><td style="padding-left:24px">公共能源费</td><td class="center">DEMO-102</td><td class="number">408,000.00</td></tr>':''}</tbody></table>`;}
function emptyMarkup(type){if(type==='success')return tableMarkup({selectable:false});const map={initial:['设置条件后开始查询','要开始，请设置相关过滤器。'],empty:['暂无匹配结果','未找到数据。尝试调整过滤器设置。'],error:['加载失败','请求未完成，筛选条件已保留。'],denied:['暂无访问权限','请联系业务管理员申请访问权限。']};if(type==='loading')return '<div class="sz-skeleton" role="status" aria-label="正在加载"><span></span><span></span><span></span><p>正在加载，请稍候…</p></div>';const x=map[type]||map.initial;return `<div class="sz-empty">${icon('empty')}<strong style="font-weight:400">${x[0]}</strong><span>${x[1]}</span>${type==='error'?'<button class="sz-btn" data-action="retry">重试</button>':''}</div>`;}
function templateShell(mode){return `<div class="template-shell"><div class="template-top"><span>seazen　新城控股　 /　示例业务</span><span>菜单搜索　　帮助</span></div><div class="template-body"><div class="template-nav"><div>招商实施管理 ⌄</div><div>招商计划</div><div>商机管理</div><div class="selected">意向合同</div><div>商务函</div></div><div class="template-main">${mode==='list'?workbench({filters:true}):mode==='tabs'?`<div class="sz-tabs"><span class="sz-tab" style="color:#427ec0;border-color:#427ec0;display:flex;align-items:center">意向合同</span><span class="sz-tab" style="display:flex;align-items:center">商务合同</span></div>${workbench()}`:formMarkup(mode==='view'?'view':'edit')}</div></div></div>`;}
function overview(){return `<div class="hero"><div><div class="eyebrow">SEAZEN · SAP UI GUIDELINES</div><h1>统一界面，<br>让 AI <span>有章可循。</span></h1><p>从一个按钮到一张业务单据，把绿洲系统的设计经验<br>整理成团队可查阅、前端可复用、AI 可执行的标准。</p><div class="hero-actions"><a class="doc-btn primary" href="#button">浏览组件 <span>→</span></a><a class="doc-btn" href="#ai">获取 AI 约束文件 ↗</a></div></div><div class="hero-art" aria-hidden="true"><span class="art-label one">color.brand · #427EC0</span><div class="system-square"><span>Aa</span><span>▤</span><span>12</span><span>↗</span></div><span class="art-label two">12px MIN · 24 / 30 px</span></div></div><div class="source-line"><span class="badge">v0.9.1 评审稿</span><span>基于 3 份内部文档 + SAP 测试环境观察</span><span>2026 / 11 / 03</span><a href="#sources">依据说明 ↗</a></div><div class="stats-strip"><div class="stat"><b>16</b><span>组件与表单规范</span></div><div class="stat"><b>04</b><span>业务页面模板</span></div><div class="stat"><b>05</b><span>通用间距档位</span></div><div class="stat"><b>HTML + MD</b><span>人和 AI 共用同一套依据</span></div></div>${section('start','从这里开始',`<div class="entry-grid"><a class="entry" href="#colors"><span class="entry-icon">◫</span><h3>设计基础</h3><p>颜色、字体、间距与布局。<br>先确定统一的视觉底层。</p><span>查看设计语言 →</span></a><a class="entry" href="#button"><span class="entry-icon">▤</span><h3>标准组件</h3><p>从选型到状态与交互。<br>用可操作的示例理解规则。</p><span>浏览组件规范 →</span></a><a class="entry" href="#ai"><span class="entry-icon">⌘</span><h3>AI 协作</h3><p>规范、Token、Skill 和验收表。<br>把约束带入每一次生成。</p><span>开始约束 AI →</span></a></div>`)}${section('preview','规则如何落到页面',specBox('意向合同 · 列表页示例',workbench({filters:true}),{flush:true})+'<p>同样的检索区、工具栏和网格表格，可以组合成不同业务页面。请勾选一条记录，观察状态如何影响按钮。</p>')}${section('boundary','先统一的部分',listRules([['01','必须','字体、颜色、间距、控件、表格、页面框架和操作状态。'],['02','可','标准框架内的信息组织、图表类型与业务内容表达。'],['03','待确认','提交审批状态、扩展组件和功能级例外。']])+'<div class="intro-note">这是一份可评审、可试用的整合稿。演示已采用用户确认的 12px 最小字号，并同步适配控件尺寸；<a href="#extensions">13 项待确认事项</a>在完成决策前保留为待确认。</div>')}`;}
function pageExtra(page){
 switch(page.kind){
 case 'principles':return section('scope','强约束与可调整空间',rulesTable([['强约束','跨页面一致性、控件样式、数据格式、按钮状态','任何生成任务必须引用。'],['可调整','字段业务排序、同类内容分组、图表选择、文案表达','不能改变业务语义、权限、审批和错误处理。'],['待评审','清单外控件、正文口径、缺失状态参数','明确提出变更，不默认获得发布批准。']]))+section('compare','正例与反例',`<div class="comparison"><div><h3>✓ 在统一结构中表达业务</h3><p>列表名称与结果数量清楚；同一套透明操作按钮；已审批使用蓝字；业务字段由产品决定。</p></div><div class="bad"><h3>× 每页重新设计一套外观</h3><p>一个区域多个主按钮、彩色状态胶囊、32px 输入框、大圆角卡片和临时新颜色，均与当前业务基线不一致。</p></div></div>`);
 case 'colors':return section('palette','语义色板',`<div class="color-grid">${DS.colorMeta.map(([key,title,usage])=>{const color=getComputedStyle(document.documentElement).getPropertyValue('--sz-'+key).trim();return `<div class="swatch"><button style="background:${color};color:${['brand','text','label','secondary','status','required','warning','error','input-border'].includes(key)?'white':'#536b88'}" data-copy="${esc(color)}" aria-label="复制${title}色值 ${esc(color)}"></button><div><strong>${title}</strong><code>${esc(color)}</code><br>${usage}</div></div>`;}).join('')}</div>`)+section('meaning','语义优先',specBox('成功状态不引入绿色',`<div class="demo-row"><button class="sz-btn primary" data-action="info">保存</button><span style="color:#427ec0">查看详情</span>${status('approved')}<div class="sz-message">ⓘ 当前为未提交单据</div></div>`));
 case 'typography':return section('type','1:1 字号样张',specBox('业务字体，不是文档阅读字号',`<div class="type-spec"><span style="font-size:14px;font-weight:400">合同管理 · 页面标题</span><small>14px / 400</small></div><div class="type-spec"><span style="font-size:12px">示例项目 A · 合同名称与表格正文</span><small>12px / 400</small></div><div class="type-spec"><span style="font-size:12px;color:#777">请输入合同名称</span><small>12px / 次要文字</small></div><div class="type-spec"><button class="sz-btn primary" data-action="info">保存</button><small>12px / 700</small></div>`,{note:'阅读层使用较大字号便于查阅；业务示例尺寸独立，不将阅读层字号输出为业务 Token。'}))+section('family','字体栈',codeBlock('font-family: "72", "72full", Arial, Helvetica,\n  "Microsoft YaHei", "PingFang SC", sans-serif;\n\n/* 生产业务根节点 */\nhtml { font-size: 12px; }'));
 case 'spacing':return section('scale','五档间距',`<div class="space-spec">${[3,6,12,24,36].map((n,i)=>`<div><div class="space-box"><i style="width:${n}px;height:${n}px"></i></div><code>${n}px</code><small>${['XS','S','M','L','XL'][i]}</small></div>`).join('')}</div>`)+section('measure','可见尺寸与占位',specBox('24px 可见高度 / 30px 占位',`<div style="display:flex;align-items:center;gap:24px"><div style="outline:1px dashed #8ca7ca;height:30px;display:flex;align-items:center"><button class="sz-btn primary">保存</button></div><input class="sz-input" aria-label="控件高度示例" placeholder="24px" style="width:180px"><span style="color:#777">虚线表示 30px 占位范围</span></div>`));
 case 'templates':return section('demo','四类页面模板',`<div class="play-controls"><button class="doc-btn ${templateMode==='list'?'primary':''}" data-template="list">A 列表页</button><button class="doc-btn ${templateMode==='tabs'?'primary':''}" data-template="tabs">B 页签列表</button><button class="doc-btn ${templateMode==='view'?'primary':''}" data-template="view">C 查看页</button><button class="doc-btn ${templateMode==='edit'?'primary':''}" data-template="edit">D 编辑页</button></div><div id="template-preview">${specBox('业务模板 · '+templateMode,templateShell(templateMode),{flush:true})}</div>`)+section('assembly','组合规则','<p>示例展示标准骨架和字段控件。新增、保存、审批、导出仅对本地虚构记录操作；不能把示例按钮策略直接当作后端权限。</p>');
 case 'permissions':return section('demo','交互策略试验台',workbench({controls:true}))+section('matrix','状态与操作矩阵',rulesTable(Object.entries(R.labels).map(([s,l])=>[l,`修改：${R.editStatuses.includes(s)?'可':'不可'}；删除：${s==='unsubmitted'?'可，逻辑删除':'不可'}`,`查看审批：${R.approvalStatuses.includes(s)?'可':'不可'}；提交审批：待配置`])) )+section('code','可执行规则示例',codeBlock(`SeazenRules.evaluate('delete', {\n  permissions: ['view', 'delete'],\n  organization: 'project',\n  selection: [{ id: 'DEMO-001', status: 'unsubmitted' }],\n  busy: false\n});\n// { visible: true, enabled: true, reason: '' }\n\n// 未提供 submitStatuses → 提交审批默认禁用\n// 实际动作还必须在服务端进行权限、状态和并发校验。`));
 case 'extensions':return section('review','待确认决策清单',`<div class="intro-note warning">以下为真实文档冲突或规范缺口。建议负责人是评审分工建议，不是已指定的责任人。</div>${reviewTable()}`)+section('addition','建议补充的体验底线',listRules([['A11Y-01','建议','键盘可达、焦点可见、图标有名称；弹窗焦点约束和关闭恢复。'],['A11Y-02','建议','小字号应经过真实设备和缩放评审；颜色不承担唯一信息。'],['UX-01','建议','区分初始、无结果、加载失败与无权限；失败后保留条件并支持重试。'],['UX-02','建议','保存或提交时防重；长文本、极值、0、空值和接口失败纳入验收。'],['GOV-06','建议','规范版本、变更记录、例外说明及视觉验收证据一起发布。']]));
 case 'ai':return section('workflow','产品经理如何使用',`<div class="flow-steps"><div class="flow-step"><b>01 / INPUT</b><h3>补齐业务上下文</h3><p>页面类型、组织范围、字段、角色权限与状态流转。</p></div><div class="flow-step"><b>02 / CONSTRAINT</b><h3>附加规范文件</h3><p>引用 MD、Token 和策略；不可只粘贴一张截图。</p></div><div class="flow-step"><b>03 / GENERATE</b><h3>在标准内生成</h3><p>先选结构，再组装控件；缺失规则显式列出。</p></div><div class="flow-step"><b>04 / REVIEW</b><h3>用证据验收</h3><p>核查截图、状态、权限与交互；通过后再交付。</p></div></div>`)+section('prompt','可复制的任务提示词',`<div class="play-controls"><label style="flex:1">本次任务<input id="ai-task" value="为意向合同管理生成列表与编辑页面" style="border:1px solid #d8e1eb;padding:6px 9px;color:#5f7289;width:100%;min-width:220px"></label><button class="doc-btn primary" data-action="generate-prompt">生成约束提示词</button></div>${codeBlock(promptText())}`)+section('files','交付给 AI 的文件',downloadList())+section('contract','AI 必须返回什么',listRules([['AI-01','必须','引用规范版本和规则 ID；声明使用的页面结构、Token 与组件。'],['AI-02','必须','待确认的业务条件不能伪装成已批准规则，提交策略未定义时默认禁用。'],['AI-03','必须','分别提供正常、只读、禁用、加载、空结果、校验失败和权限不足的实现或说明。'],['AI-04','必须','提交视觉截图、交互检查结果、偏离项和待确认项，不能只有“已遵守规范”的声明。']]) );
 case 'checklist':return section('checks','逐项验收',`<div style="display:flex;align-items:center;justify-content:space-between"><span id="check-progress" style="font-size:12px;color:#7a8da4"></span><div><button class="doc-btn small" data-action="download-checks">导出检查结果</button> <button class="doc-btn small" data-action="reset-checks">重置</button></div></div><div class="progress-track"><span id="check-progress-bar"></span></div><div class="checklist">${DS.checks.map((x,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}"><span><strong>${esc(x[0])} · ${esc(x[1])}</strong><small>${esc(x[2])}</small></span></label>`).join('')}</div><p style="font-size:12px;color:#8e9daf">检查进度仅保存在当前浏览器；手动勾选不能代替测试证据或业务批准。</p>`);
 case 'downloads':return section('files','完整交付资源',downloadList())+section('use','两种使用方式',rulesTable([['前端展示','直接打开 index.html，或将 dist 部署为静态站点','所有样式和脚本均为本地资源，无外部 CDN。'],['产品约束 AI','附加 design-guidelines.md、tokens.json、business-rules.json、checklist.md','可跨 AI 工具使用，不要求安装 Codex Skill。'],['Codex Skill','解压 seazen-sap-ui-skill.zip 到技能目录','目录包含 SKILL.md、references、agents；仅适用绿洲 SAPUI5。'],['生产实现','沿用原生 SAPUI5 组件与真实接口','本交付的 HTML 控件示例不替代 SAPUI5 运行时、后端校验或权限系统。']]))+section('version','版本状态','<div class="intro-note">v0.9.1-review · 2026/11/03。该交付是整合评审稿；待确认项完成决策后，更新规则、Token、示例和验收表，再发布 v1.0。</div>');
 case 'sources':return section('confirmed','已确认的规范调整',rulesTable(DS.decisions.map(d=>[d.id+' · '+d.topic,d.result,d.source])))+section('sources','来源登记',Object.entries(DS.sources).map(([id,x])=>`<div style="padding:18px 0;border-bottom:1px solid #e9edf2"><span class="badge">${id}</span> <a href="${x.url}" ${id!=='A1'?'target="_blank" rel="noopener"':''}>${x.name} ↗</a><span style="float:right;color:#9aa8b8;font-size:12px">${x.version}</span><p style="font-size:12px;color:#8291a3;margin-bottom:0">${x.note}</p></div>`).join(''))+section('observations','实页观察与规范之间的差异',rulesTable([['虚拟项目','看到了查询标题、结果数量与网格列表；开业日期显示为连字符格式','现有页面不全部合规；规范示例使用 S1 规定的斜杠日期。'],['意向合同','工具栏保留不可用操作，空结果有调整过滤器提示','新建路径报 Duplicate resource，未成功查看详情。'],['商机管理','多值筛选、值帮助、日期区间与初始空态；新增有组织范围校验','组织提示允许事业部/区域/项目，需作为功能例外确认。'],['测量边界','本次做视觉/行为观察，原始像素引用 S1 文档记录，当前字号与关联尺寸按 U1 适配','原始控件高度不再作为当前字号适配尺寸；原始 MD 与全部 UI5 API 仍待前端核验。']]))+section('review','冲突与评审',reviewTable())+section('history','本次整合变更',rulesTable([['2026/11/03','v0.9.1-review','按用户确认统一最小字号 12px，正文 12px、标题 14px，并同步控件与表格尺寸、Token、文档和 Skill。'],['2026/11/03','v0.9.0-review','整理交互文档站、独立 CSS / JSON、按钮策略、页面模板、验收表与 AI Skill。'],['待发布','v1.0','统一审批与组织例外，确认扩展状态和组件后由团队正式发布。']]));
 default:return '';
 }
}
function reviewTable(){return `<div class="responsive-table"><table class="prop-table"><thead><tr><th>ID / 议题</th><th>差异与当前处理</th><th>建议评审角色</th></tr></thead><tbody>${DS.review.map(x=>`<tr><td><code>${x[0]}</code><br>${x[1]}</td><td>${x[2]}</td><td>${x[3]}<br><span class="badge proposed">${x[4]}优先级 · 待确认</span></td></tr>`).join('')}</tbody></table></div>`;}
function downloadList(){const files=[['完整交付包','seazen-sap-design-system.zip','ZIP','HTML / CSS / JS / MD / Token / Skill'],['设计规范 Markdown','design-guidelines.md','MD','供产品经理与 AI 阅读'],['设计 Token','tokens.json','JSON','颜色、字号、间距、控件参数'],['独立控件 CSS','controls.css','CSS','配合 tokens.css 使用'],['CSS 变量','tokens.css','CSS','业务样式映射'],['业务按钮策略','business-rules.json','JSON','来源、状态集合与待确认项'],['视觉验收清单','checklist.md','MD','生成后验收与评审'],['AI 提示词模板','ai-task-template.md','MD','产品需求填写入口'],['Codex Skill','seazen-sap-ui-skill.zip','ZIP','可移植技能包'],['可执行业务规则','business-rules.js','JS','纯函数示例与状态判断']];return `<div class="download-list">${files.map(([t,f,e,d])=>`<a class="download-row" href="downloads/${f}" download><span class="file-icon">${e}</span><span><b>${t}</b><small>${d}</small></span><span>↓</span></a>`).join('')}</div>`;}
function promptText(task='为意向合同管理生成列表与编辑页面'){return `任务：${task}\n\n适用规范：绿洲 SAP UI v0.9.1-review（评审稿）。\n先读取 design-guidelines.md、tokens.json、business-rules.json 和 checklist.md。\n1. 使用现有 SAPUI5 Compact 体系；文档组织可参考 Ant Design，业务外观沿用本规范。\n2. 根字号 12px；所有可见文字不小于 12px；正文 12px、标题 14px；控件可见高 24px、占位 30px。\n3. 品牌蓝 #427EC0；已审批也用品牌蓝。通用间距只用 3/6/12/24/36px。\n4. 先选择 A 列表 / B 页签列表 / C 查看 / D 编辑结构，再组装标准控件。\n5. 工具栏透明文字按钮；一个区域至多一个主按钮；前置条件不满足时置灰并说明原因。\n6. 按 BIZ-01～08 实现组织、状态、选择、权限和逻辑删除；服务端再次校验。\n7. 提交审批状态未确认时禁用；商机组织例外、抽屉/开关等缺口列入待确认。\n8. 正常、只读、禁用、加载、空结果、失败和字段校验均需覆盖；成功/失败不使用 Toast。\n9. 仅使用虚构数据与占位接口，不自动提交真实单据。\n\n输出：页面与代码、规则 ID 对照、目标视口截图、交互验证结果、偏离项和待确认项。\n本次业务参数：组织范围[待填]；角色权限[待填]；字段与单位[待填]；\n状态流转[待填]；审批可用条件[待填]；导出范围[待填]。\n不得用视觉规则替代业务确认，不得声称评审稿已正式发布。`;}
function resetDemo(){records=baseRecords();selected=new Set(['DEMO-001']);org='project';role='editor';busy=false;query='';filterStatus='';sortDesc=false;}
function sidebar(){let group='';$('#sidebar').innerHTML='<div class="sidebar-label">DESIGN DOCUMENTATION</div>'+DS.pages.map(p=>{const heading=p.group!==group?`${group?'</div>':''}<div class="nav-group"><h2>${p.group}</h2>`:'';group=p.group;return heading+`<a class="nav-link" href="#${p.id}" data-page="${p.id}">${p.title}${p.id==='extensions'?'<small>'+DS.review.length+'</small>':p.id==='downloads'?'<small>↓</small>':''}</a>`;}).join('')+'</div><div class="sidebar-foot">SAPUI5 · Fiori 3 · Compact<br>人、组件与 AI 使用同一套规则。<br>整合日期 2026 / 11 / 03</div>';}
function render(){const [id='overview',anchor]=location.hash.slice(1).split('/');const page=DS.pages.find(p=>p.id===id)||DS.pages[0];if(page.id===currentPage&&anchor){$('#'+anchor)?.scrollIntoView();return;}closeModal(false);currentPage=page.id;document.title=`${page.title} · 绿洲 SAP UI 设计规范`;
let body=page.kind==='overview'?overview():`<header class="page-head"><div class="eyebrow">${page.group.replace(' · ',' / ')}</div><h1>${page.title}<span class="en">${page.en}</span></h1><p>${page.desc}</p>${sourceLine(page)}</header>${page.pending?`<div class="intro-note warning"><strong>待确认</strong>　${page.pending}</div>`:''}${page.rules?section('rules','使用规则',listRules(page.rules)):''}${demos(page.kind)?section('demo','代码演示',demos(page.kind)):''}${pageExtra(page)}${page.specs?section('specs','规格与使用场景',rulesTable(page.specs)):''}`;
const idx=DS.pages.indexOf(page),prev=DS.pages[idx-1],next=DS.pages[idx+1];body+=`<div class="footer-nav">${prev?`<a href="#${prev.id}">← ${prev.title}</a>`:'<span></span>'}${next?`<a href="#${next.id}">${next.title} →</a>`:''}</div><footer class="footer-meta"><span>绿洲 SAP UI · v0.9.1 评审稿</span><span>依据、示例与补充建议均可追溯</span></footer>`;
$('#main').innerHTML=body;$$('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===page.id));$$('.top-nav a').forEach(x=>x.classList.toggle('active',x.dataset.nav===page.nav));$('#page-toc').innerHTML='<b>本页目录</b>'+$$('#main>.doc-section').map(x=>`<a href="#${page.id}/${x.id}">${x.querySelector('h2').textContent}</a>`).join('');$('#sidebar').classList.remove('open');$('#mobile-nav').setAttribute('aria-expanded','false');if(page.id==='checklist')restoreChecks();if(page.id==='permissions'){$('#policy-org').value=org;$('#policy-role').value=role;$('#policy-busy').checked=busy;$('#policy-status').value=records[0].status;}if($('#filter-status'))$('#filter-status').value=filterStatus;window.scrollTo(0,0);if(anchor)setTimeout(()=>$('#'+anchor)?.scrollIntoView(),0);
}
function openModal({title,body,small=false,error=false,buttons=[{text:'确定',primary:true,action:'close-modal'}],onConfirm=null,focusSelector=null}){if(!$('#modal-root').innerHTML)modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="sz-modal-backdrop"><section class="sz-modal ${small?'small':''} ${error?'error':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="sz-modal-header" id="modal-title">${esc(title)}<button data-action="close-modal" aria-label="关闭弹窗">×</button></header><div class="sz-modal-body">${body}</div><footer class="sz-modal-footer">${buttons.map(b=>`<button class="sz-btn ${b.primary?'primary':''}" data-action="${b.action}">${b.text}</button>`).join('')}</footer></section></div>`;window.modalConfirm=onConfirm;document.body.style.overflow='hidden';const focus=focusSelector?$(focusSelector):$('#modal-root input')||$('#modal-root .sz-modal-footer button')||$('#modal-root button');focus?.focus();}
function closeModal(restore=true){if(!$('#modal-root').innerHTML)return;$('#modal-root').innerHTML='';document.body.style.overflow='';window.modalConfirm=null;if(restore&&modalReturn?.isConnected)modalReturn.focus();}
function info(text='操作演示成功。此页面使用虚构数据，没有写入任何真实业务系统。'){openModal({title:'信息',body:`<p>${esc(text)}</p>`,small:true});}
function openValueHelp(target){window.valueHelpTarget=target;openModal({title:'选择项目',body:`<div class="sz-scope"><input class="sz-input" id="value-search" aria-label="搜索项目" placeholder="搜索项目名称"><div id="value-results">${valueResults('')}</div></div>`,buttons:[{text:'确定',primary:true,action:'confirm-value'},{text:'取消',action:'close-modal'}]});}
function valueResults(q){const list=['示例项目 A','示例项目 B','示例项目 C'].filter(n=>n.toLowerCase().includes(q.toLowerCase()));return `<table class="sz-table responsive" style="min-width:0"><thead><tr><th style="width:30px">选择</th><th>项目编码</th><th>项目名称</th></tr></thead><tbody>${list.map((n,i)=>`<tr><td class="center"><input class="sz-radio" type="radio" name="value-project" value="${n}" ${i===0?'checked':''} aria-label="选择${n}"></td><td class="center">DEMO-${n.slice(-1)}</td><td>${n}</td></tr>`).join('')||'<tr><td colspan="3">无匹配项目</td></tr>'}</tbody></table>`;}
function openCalendar(target,keep=false){if(!keep){calendarTarget=target;const raw=$('#'+target)?.value||'2026/11/03';const m=raw.match(/^(\d{4})\/(\d{2})/);calendarYear=m?+m[1]:2026;calendarMonth=m?+m[2]-1:10;}const first=new Date(calendarYear,calendarMonth,1).getDay(),days=new Date(calendarYear,calendarMonth+1,0).getDate();const cells=Array.from({length:first},()=>'<span></span>').concat(Array.from({length:days},(_,i)=>`<button class="sz-btn transparent" data-action="choose-date" data-date="${calendarYear}/${String(calendarMonth+1).padStart(2,'0')}/${String(i+1).padStart(2,'0')}">${i+1}</button>`)).join('');openModal({title:'选择日期',small:true,body:`<div class="sz-scope"><div style="display:flex;align-items:center;justify-content:space-between"><button class="sz-btn transparent" data-action="calendar-prev" aria-label="上个月">‹</button><span>${calendarYear} / ${String(calendarMonth+1).padStart(2,'0')}</span><button class="sz-btn transparent" data-action="calendar-next" aria-label="下个月">›</button></div><div style="display:grid;grid-template-columns:repeat(7,1fr);text-align:center;margin-top:12px">${['日','一','二','三','四','五','六'].map(t=>`<span style="color:#777">${t}</span>`).join('')}${cells}</div></div>`,buttons:[{text:'取消',action:'close-modal'}]});}
function validateDates(){const el=$('#date-feedback');if(!el)return;const inputs=['single-date','range-start','range-end'].map(id=>$('#'+id));const bad=inputs.filter(i=>i.value&&R.formatDate(i.value)==='—');inputs.forEach(i=>i.setAttribute('aria-invalid',bad.includes(i)?'true':'false'));if(bad.length){el.textContent='请输入有效日期，格式为 yyyy/MM/dd。';el.style.color='#bb0000';return;}const start=$('#range-start').value,end=$('#range-end').value;if(start&&end&&start>end){el.textContent='开始日期不能晚于结束日期。';el.style.color='#bb0000';return;}el.textContent=start&&end?`已选择 ${start} 至 ${end}。`:'日期有效；日期区间可继续选择。';el.style.color='#427ec0';}
function validateForm(){const errors=[];const name=$('#form-name'),area=$('#form-area'),amount=$('#form-amount'),date=$('#form-date');$$('#demo-business-form .sz-error-field').forEach(x=>{x.classList.remove('sz-error-field');x.removeAttribute('aria-invalid');});if(!name?.value.trim())errors.push([name,'请填写合同名称']);if(area?.value!==''&&(!Number.isFinite(Number(area.value.replaceAll(',','')))||Number(area.value.replaceAll(',',''))<0))errors.push([area,'建筑面积必须是非负数，空值与 0 含义不同']);if(amount?.value!==''&&!Number.isFinite(Number(amount.value.replaceAll(',',''))))errors.push([amount,'合同金额格式无效']);if(date?.value&&R.formatDate(date.value)==='—')errors.push([date,'签订日期应为有效的 yyyy/MM/dd']);errors.forEach(([e])=>{e.classList.add('sz-error-field');e.setAttribute('aria-invalid','true');});const errorbox=$('#form-errors');if(errorbox)errorbox.innerHTML=errors.map(([e,t])=>`<div id="${e.id}-error"><button class="sz-btn transparent" style="color:#bb0000" data-action="focus-field" data-target="${e.id}">${esc(t)}</button></div>`).join('');if(errors.length){errors[0][0].focus();announce(`发现 ${errors.length} 个校验问题`);return false;}return true;}
function saveForm(button){if(!validateForm())return;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='保存中…';setTimeout(()=>{if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.textContent='保存';}info('示例保存成功。数据仅用于演示；真实业务需由服务端校验与持久化。');},700);}
function business(action){const check=R.evaluate(action,context());if(!check.enabled||!check.visible)return;const row=context().selection[0];if(action==='create'||action==='edit'){openModal({title:action==='create'?'新增合同 · 本地演示':'修改合同 · 本地演示',body:`<div class="sz-scope">${formMarkup()}</div>`,buttons:[{text:'关闭',action:'close-modal'}]});if(action==='edit'&&row){$('#form-name').value=row.name;$('#form-area').value=R.formatNumber(row.area);$('#form-amount').value=R.formatNumber(row.amount);$('#form-date').value=row.date;}return;}if(action==='view'){openModal({title:'查看单据 · '+row.id,body:`<div class="sz-scope">${formMarkup('view')}</div>`,buttons:[{text:'关闭',action:'close-modal'}]});$('#form-name').value=row.name;$('#form-area').value=R.formatNumber(row.area);$('#form-amount').value=R.formatNumber(row.amount);return;}if(action==='delete'){openModal({title:'确认逻辑删除',body:`<p>将示例单据 ${esc(row.id)} 标记为已删除。该操作不会物理移除记录。</p>`,small:true,buttons:[{text:'确定',primary:true,action:'confirm-modal'},{text:'取消',action:'close-modal'}],onConfirm:()=>{records=records.map(r=>r.id===row.id?R.logicalDelete(r):r);selected.delete(row.id);closeModal();redrawWorkbench();info('示例单据已标记为逻辑删除。可使用“重置示例”恢复演示数据。');}});return;}if(action==='viewApproval'){openModal({title:'审批记录 · 虚构示例',body:rulesTable([['当前状态',R.labels[row.status],'展示状态，不推导完整审批流程。'],['审批记录','示例审批节点','实际审批节点和人员由 BPM 接口返回。']]),small:true});return;}if(action==='export'){const csv='\uFEFF'+['单据编号,状态,合同名称,金额(元)',...visibleRecords().map(r=>[r.id,R.labels[r.status],r.name,r.amount??''].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','))].join('\r\n');downloadBlob(csv,'虚构合同示例.csv','text/csv;charset=utf-8');info('已导出当前虚构查询结果。真实敏感字段导出需单独授权。');}}
function downloadBlob(text,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function announce(text){$('#announcer').textContent=text;}
async function copy(text,button){try{if(navigator.clipboard)await navigator.clipboard.writeText(text);else{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();if(!document.execCommand('copy'))throw Error('copy');t.remove();}announce('已复制');if(button){const before=button.textContent;button.textContent='已复制';setTimeout(()=>{if(button.isConnected)button.textContent=before;},1000);}}catch{openModal({title:'复制内容',body:`<textarea readonly style="width:100%;height:220px" aria-label="手动复制内容">${esc(text)}</textarea>`,small:true});}}
function restoreChecks(){let values=[];try{values=JSON.parse(localStorage.getItem('seazen-checks-v09')||'[]');}catch{}$$('[data-check]').forEach(x=>{x.checked=values.includes(+x.dataset.check);x.closest('label').classList.toggle('checked',x.checked);});updateCheckProgress();}
function updateCheckProgress(){const all=$$('[data-check]'),checked=all.filter(x=>x.checked);if($('#check-progress'))$('#check-progress').textContent=`已检查 ${checked.length} / ${all.length} 项`;if($('#check-progress-bar'))$('#check-progress-bar').style.width=`${all.length?checked.length/all.length*100:0}%`;try{localStorage.setItem('seazen-checks-v09',JSON.stringify(checked.map(x=>+x.dataset.check)));}catch{} }
function searchOpen(){openModal({title:'搜索规范',body:'',small:true});$('#modal-root').innerHTML=`<div class="sz-modal-backdrop"><section class="search-panel" role="dialog" aria-modal="true" aria-label="搜索规范"><input class="search-input" id="search-input" aria-label="输入控件或规范关键词" placeholder="搜索控件、规则、业务场景…"><div class="search-results" id="search-results">${searchResults('')}</div><div class="search-hint">ESC 关闭　 ·　搜索标题、英文名和规范内容</div></section></div>`;$('#search-input').focus();}
function searchResults(q){const word=q.trim().toLowerCase();const results=DS.pages.filter(p=>JSON.stringify(p).toLowerCase().includes(word));return results.map(p=>`<a class="search-result" href="#${p.id}" data-search-result>${p.title} <span style="font-size:12px;color:#a0adbd">${p.en}</span><small>${p.desc}</small></a>`).join('')||'<div class="search-empty">没有匹配项，试试“表格”“审批”或“Token”。</div>';}
document.addEventListener('click',event=>{
 const target=event.target.closest('button,a,[data-row]');if(!target)return;
 if(target.classList.contains('skip-link')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}
 if(target.id==='open-search'){searchOpen();return;}if(target.id==='mobile-nav'){const open=$('#sidebar').classList.toggle('open');target.setAttribute('aria-expanded',String(open));return;}
 if(target.hasAttribute('data-search-result')){closeModal();return;}
 if(target.hasAttribute('data-copy')){copy(target.dataset.copy,target);return;}if(target.hasAttribute('data-copy-code')){copy(target.parentElement.querySelector('pre').textContent,target);return;}
 if(target.dataset.template){templateMode=target.dataset.template;currentPage='';render();return;}
 if(target.dataset.row&&!event.target.closest('input,button,a')){selected.has(target.dataset.row)?selected.delete(target.dataset.row):selected.add(target.dataset.row);redrawWorkbench();return;}
 const action=target.dataset.action;if(!action)return;
 if(action==='close-modal'){closeModal();return;}if(action==='confirm-modal'){window.modalConfirm?.();return;}
 if(action==='info'){info();return;}if(action==='error-demo'){openModal({title:'错误',body:'<p>示例请求未完成，请检查必填字段或稍后重试。已经填写的内容会保留。</p>',small:true,error:true,buttons:[{text:'关闭',action:'close-modal'}]});return;}
 if(action==='confirm-demo'){openModal({title:'离开当前页面？',body:'<p>示例中的修改尚未保存。确认后离开，取消则继续编辑。</p>',small:true,buttons:[{text:'确定',primary:true,action:'close-modal'},{text:'取消',action:'close-modal'}]});return;}
 if(action==='loading-button'){target.disabled=true;target.textContent='保存中…';target.setAttribute('aria-busy','true');setTimeout(()=>{target.disabled=false;target.textContent='体验加载';target.removeAttribute('aria-busy');info('示例操作完成。');},800);return;}
 if(action==='valuehelp'){openValueHelp(target.dataset.target);return;}
 if(action==='confirm-value'){const value=$('input[name="value-project"]:checked')?.value;if(!value){announce('请先选择项目');return;}const inputEl=document.getElementById(window.valueHelpTarget);if(inputEl)inputEl.value=value;closeModal();announce('已选择'+value);return;}
 if(action==='calendar'){openCalendar(target.dataset.target);return;}
 if(action==='calendar-prev'||action==='calendar-next'){calendarMonth+=action==='calendar-prev'?-1:1;if(calendarMonth<0){calendarMonth=11;calendarYear--;}if(calendarMonth>11){calendarMonth=0;calendarYear++;}openCalendar(calendarTarget,true);return;}
 if(action==='choose-date'){const el=document.getElementById(calendarTarget);if(el){el.value=target.dataset.date;el.dispatchEvent(new Event('change',{bubbles:true}));}closeModal();return;}
 if(action==='remove-token'){tokens.splice(+target.dataset.index,1);$('#tokens-box').innerHTML=tokenMarkup();$('#token-input').focus();return;}
 if(action==='upload'){$('#demo-file').click();return;}if(action==='remove-file'){target.closest('li').remove();return;}
 if(action==='toggle-filter'){const el=$('#demo-filter');el.classList.toggle('collapsed');target.setAttribute('aria-expanded',String(!el.classList.contains('collapsed')));return;}
 if(action==='query'){query=$('#filter-query')?.value||'';filterStatus=$('#filter-status')?.value||'';selected.clear();redrawWorkbench();announce(`查询得到 ${visibleRecords().length} 条虚构结果`);return;}
 if(action==='reset-filter'){query='';filterStatus='';$('#filter-query').value='';$('#filter-status').value='';redrawWorkbench();return;}
 if(action==='sort'){sortDesc=!sortDesc;redrawWorkbench();return;}
 if(action==='business'){business(target.dataset.business);return;}if(action==='reset-demo'){resetDemo();currentPage='';render();return;}
 if(action==='tree'){treeOpen=!treeOpen;const scope=target.closest('.sz-scope');scope.innerHTML=treeMarkup();return;}
 if(action==='tab'){const tabs=$$('[role="tab"]');tabs.forEach(t=>{const on=t===target;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;});const panel=$('#tab-panel');panel.setAttribute('aria-labelledby',target.id);panel.innerHTML=target.dataset.tab==='basic'?'合同编号：DEMO-001　　归属项目：示例项目 A　　状态：未提交':target.dataset.tab==='detail'?tableMarkup({selectable:false,simple:true}):'示例合同.pdf　　示例附件.xlsx（仅展示虚构文件名）';return;}
 if(action==='retry'){$('#state-demo').innerHTML=emptyMarkup('loading');setTimeout(()=>{if($('#state-demo')){$('#state-demo').innerHTML=tableMarkup({selectable:false});$('#state-select').value='success';announce('重试成功，已加载虚构数据');}},800);return;}
 if(action==='save-form'){saveForm(target);return;}if(action==='focus-field'){document.getElementById(target.dataset.target)?.focus();return;}
 if(action==='form-back'){if($('#modal-root').innerHTML){closeModal();return;}openModal({title:'返回列表？',body:'<p>该示例未连接真实业务。确认后返回列表模板。</p>',small:true,buttons:[{text:'确定',primary:true,action:'confirm-modal'},{text:'取消',action:'close-modal'}],onConfirm:()=>{closeModal();templateMode='list';location.hash='templates';currentPage='';render();}});return;}
 if(action==='generate-prompt'){const pre=$('#ai-task').closest('section').querySelector('pre');pre.textContent=promptText($('#ai-task').value.trim()||'生成标准业务页面');return;}
 if(action==='reset-checks'){$$('[data-check]').forEach(x=>{x.checked=false;x.closest('label').classList.remove('checked');});updateCheckProgress();return;}
 if(action==='download-checks'){const text=`# 绿洲 SAP UI 验收记录\n\n版本：${DS.version}\n导出时间：${new Date().toISOString()}\n说明：手动检查记录，不等于自动验证通过。\n\n`+DS.checks.map((x,i)=>`- [${$(`[data-check="${i}"]`).checked?'x':' '}] ${x[0]} · ${x[1]}：${x[2]}`).join('\n');downloadBlob(text,'绿洲-视觉验收记录.md');return;}
});
document.addEventListener('change',event=>{const t=event.target;if(t.hasAttribute('data-select-row')){t.checked?selected.add(t.dataset.selectRow):selected.delete(t.dataset.selectRow);redrawWorkbench();}if(t.hasAttribute('data-select-all')){visibleRecords().forEach(r=>t.checked?selected.add(r.id):selected.delete(r.id));redrawWorkbench();}if(t.id==='policy-org'){org=t.value;redrawWorkbench();}if(t.id==='policy-role'){role=t.value;redrawWorkbench();}if(t.id==='policy-busy'){busy=t.checked;redrawWorkbench();}if(t.id==='policy-status'){records[0].status=t.value;redrawWorkbench();}if(t.matches('[data-multiselect]')){$('#select-summary').textContent=$$('[data-multiselect]:checked').map(x=>R.labels[x.value]).join('、')||'尚未选择';}if(t.id==='demo-file'){$('#file-list').innerHTML=[...t.files].map(f=>`<li style="margin:6px 0">${esc(f.name)} <span style="color:#777">(${R.formatNumber(f.size/1024)} KB)</span><button class="sz-btn transparent" data-action="remove-file" aria-label="移除${esc(f.name)}">移除</button></li>`).join('');}if(t.id==='state-select')$('#state-demo').innerHTML=emptyMarkup(t.value);if(['single-date','range-start','range-end'].includes(t.id))validateDates();if(t.hasAttribute('data-check')){t.closest('label').classList.toggle('checked',t.checked);updateCheckProgress();}});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='search-input')$('#search-results').innerHTML=searchResults(t.value);if(t.id==='value-search')$('#value-results').innerHTML=valueResults(t.value);if(['single-date','range-start','range-end'].includes(t.id))validateDates();});
document.addEventListener('submit',event=>event.preventDefault());
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchOpen();return;}if(event.key==='Escape'&&$('#modal-root').innerHTML){event.preventDefault();closeModal();return;}if(event.key==='Tab'&&$('#modal-root').innerHTML){const focusable=$$('#modal-root button:not(:disabled),#modal-root input:not(:disabled),#modal-root select,#modal-root textarea,#modal-root a[href]');const first=focusable[0],last=focusable[focusable.length-1];if(first&&last){if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}if(event.target.id==='token-input'&&event.key==='Enter'){event.preventDefault();const v=event.target.value.trim();if(v&&!tokens.includes(v))tokens.push(v);$('#tokens-box').innerHTML=tokenMarkup();$('#token-input').focus();}if(event.target.id==='filter-query'&&event.key==='Enter'){event.preventDefault();$('[data-action="query"]').click();}if(event.target.getAttribute('role')==='tab'&&['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('[role="tab"]');const i=tabs.indexOf(event.target);const next=event.key==='Home'?tabs[0]:event.key==='End'?tabs[tabs.length-1]:tabs[(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next.click();next.focus();}});
window.addEventListener('hashchange',render);sidebar();render();
})();
